#!/bin/sh
# Import BUK agosto → Superpelu (clientes + citas)
# Pegar entero en la terminal del Postgres de Coolify:
#   sh /tmp/coolify-run-buk-import.sh
# o:  sh <<'EOS'
#     ...contenido...
# EOS

set -e
TMP=$(mktemp)
B64=$(mktemp)
trap 'rm -f "$TMP" "$B64"' EXIT

cat > "$B64" <<'B64EOF'

B64EOF

base64 -d "$B64" | gzip -d > "$TMP"
echo "Ejecutando import ($(wc -c < "$TMP") bytes SQL)..."
psql -U postgres -d postgres -v ON_ERROR_STOP=1 -f "$TMP"
echo "OK"
